import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Service Overview: What We Are Trying to Achieve","description":"","frontmatter":{},"headers":[],"relativePath":"service-overview.md","filePath":"service-overview.md","lastUpdated":1782337934000}'),o={name:"service-overview.md"};function l(r,e,n,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="service-overview-what-we-are-trying-to-achieve" tabindex="-1">Service Overview: What We Are Trying to Achieve <a class="header-anchor" href="#service-overview-what-we-are-trying-to-achieve" aria-label="Permalink to &quot;Service Overview: What We Are Trying to Achieve&quot;">​</a></h1><p>This document captures the intent and goals of the <code>auto-complete</code> service.</p><h2 id="one-line-summary" tabindex="-1">One-line summary <a class="header-anchor" href="#one-line-summary" aria-label="Permalink to &quot;One-line summary&quot;">​</a></h2><p>Build and maintain clean, searchable Meilisearch datasets that will power a travel <strong>autosuggest / autocomplete</strong> experience — so a user typing a few characters instantly gets relevant places, airports, hotels, and tourist attractions.</p><h2 id="the-product-goal" tabindex="-1">The product goal <a class="header-anchor" href="#the-product-goal" aria-label="Permalink to &quot;The product goal&quot;">​</a></h2><p>When a user starts typing in a travel search box, they should get fast, relevant suggestions for:</p><ul><li><strong>Places</strong>: cities, regions, neighborhoods, islands.</li><li><strong>Airports</strong>: airport and airfield locations (enriched with IATA codes).</li><li><strong>Accommodations</strong>: hotels, hostels, apartments, guest houses.</li><li><strong>Discovery</strong>: tourist attractions, stadiums, historic sites, parks, restaurants, shopping malls.</li></ul><p>This repo owns the <strong>data side</strong> of that experience. The actual HTTP autosuggest API that serves queries to end users is intentionally <strong>out of scope</strong> here. We are building the pipeline that keeps the search indices correct, fresh, and production-ready.</p><h2 id="what-this-service-actually-does" tabindex="-1">What this service actually does <a class="header-anchor" href="#what-this-service-actually-does" aria-label="Permalink to &quot;What this service actually does&quot;">​</a></h2><p>It is a <strong>data pipeline</strong>, not a web service. It runs in stages:</p><ol><li><p><strong>Fetch</strong> raw source data</p><ul><li>OSM (Geofabrik country extracts) for places, admin boundaries, and POIs.</li><li>Uses ETag checks and local manifests so unchanged countries are skipped entirely.</li></ul></li><li><p><strong>Transform</strong> raw data into normalized NDJSON documents</p><ul><li>Executed per-country to allow horizontal scalability and incremental build caching.</li><li>Extracts 19 distinct entity classes, mapping custom fields like <code>iata_code</code>, <code>star_rating</code>, and <code>cuisine</code>.</li><li>Normalizes multilingual names (<code>name:*</code> tags) and alt names into a searchable flat index.</li></ul></li><li><p><strong>Enrich</strong> place records</p><ul><li>Adds popularity/quality signals (Wikidata/Wikipedia-derived pageviews and sitelinks) via a local SQLite cache.</li><li>Unchanged country builds reuse their previously enriched files, skipping CPU-intensive network/database hits.</li></ul></li><li><p><strong>Index</strong> into Meilisearch using blue/green deploys</p><ul><li>Streams all per-country enriched documents directly into one shadow build index.</li><li>Builds a shadow index, validates it (golden queries + doc counts), then atomically swaps it into the live index name.</li><li>Live index never serves partial/broken data.</li></ul></li><li><p><strong>Cleanup / operate</strong></p><ul><li>Retain only recent shadow builds, prune old manifests.</li></ul></li></ol><h2 id="why-it-is-built-this-way-the-real-objectives" tabindex="-1">Why it is built this way (the real objectives) <a class="header-anchor" href="#why-it-is-built-this-way-the-real-objectives" aria-label="Permalink to &quot;Why it is built this way (the real objectives)&quot;">​</a></h2><ul><li><strong>Relevance</strong>: normalize multilingual names, alt names, and search terms so suggestions match how people actually type.</li><li><strong>Freshness</strong>: re-runnable on a schedule without manual babysitting.</li><li><strong>Planet-Scale Readiness</strong>: Incremental country builds allow processing the entire planet in small, cached slices instead of one giant file.</li><li><strong>Safety / zero-downtime updates</strong>: blue/green indexing means a bad build never replaces a good live index.</li><li><strong>Correctness guarantees</strong>: golden-query validation + non-empty checks catch broken data before it goes live.</li><li><strong>Operational resilience</strong>: locks prevent duplicate runs, and cached fallbacks survive upstream outages.</li></ul><h2 id="what-done-healthy-looks-like" tabindex="-1">What &quot;done / healthy&quot; looks like <a class="header-anchor" href="#what-done-healthy-looks-like" aria-label="Permalink to &quot;What &quot;done / healthy&quot; looks like&quot;">​</a></h2><ul><li>A live <code>places</code> index exists with a non-trivial doc count and passes its golden queries.</li><li>All document IDs are valid Meilisearch IDs.</li><li>Old shadow <code>__build_</code> indices are pruned.</li><li><code>make run</code> completes end-to-end without manual intervention.</li></ul><h2 id="out-of-scope-for-this-repo" tabindex="-1">Out of scope (for this repo) <a class="header-anchor" href="#out-of-scope-for-this-repo" aria-label="Permalink to &quot;Out of scope (for this repo)&quot;">​</a></h2><ul><li>The user-facing autosuggest HTTP API / query service.</li><li>Frontend search UI.</li><li>Ranking experiments beyond the baseline Meilisearch settings.</li></ul>',17)])])}const g=i(o,[["render",l]]);export{p as __pageData,g as default};
